const assert = require("node:assert");
const { delivery } = require("./delivery.js");

assert.strictEqual(delivery("pickup", 100, 1), 0);
assert.strictEqual(delivery("courier", 1000, 1), 300);
assert.strictEqual(delivery("courier", 2999, 1), 300);
assert.strictEqual(delivery("courier", 3000, 1), 0);
assert.strictEqual(delivery("post", 500, 1), 170);
assert.strictEqual(delivery("post", 500, 1.2), 190);
assert.strictEqual(delivery("post", 500, 3), 210);
console.log("ok");
